    display: flex;
    gap: 1.5rem;
}

.social-link {
    text-decoration: none;
    color: #333;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 500;
    transition: color 0.3s;
}

.social-link:hover {
    color: #00BBD4;
}

.social-link i {
    font-size: 1.2rem;
}

.company-role {
    color: #666;
    font-size: 1.1rem;
    margin: 0.5rem 0 1rem;
}

.achievement-list {
    list-style: none;
    margin: 1.5rem 0;
}

.achievement-list li {
    margin-bottom: 0.8rem;
    padding-left: 1.5rem;
    position: relative;
}

.achievement-list li::before {
    content: "→";
    position: absolute;
    left: 0;
    color: #00BBD4;
}

.speaking-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-top: 2rem;
}

.speaking-item {
    background: #fff;
    padding: 2rem;
    border-radius: 12px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.05);
    transition: transform 0.3s;
}

.speaking-item:hover {
    transform: translateY(-5px);
}

.speaking-item h3 {
    color: #333;
    margin-bottom: 0.5rem;
}

.speaking-item p {
    color: #666;
}

.newsletter-signup {
    background: linear-gradient(to right, #00F0B7, #01B2D5);
    padding: 3rem;
    border-radius: 12px;
    text-align: center;
    color: white;
    margin-top: 4rem;
}

.newsletter-signup h3 {
    font-size: 1.8rem;
    margin-bottom: 1rem;
}

.newsletter-signup .btn {
    background: white;
    color: #01B2D5;
    margin-top: 1.5rem;
}

.newsletter-signup .btn:hover {
    background: rgba(255,255,255,0.9);
}

/* Animations */
.speaking-item, .project-inner, .featured-article {
    animation: fadeInUp 0.8s ease-out;
}

@keyframes fadeIn {
    from {opacity: 0; transform: translateY(30px);}
    to {opacity: 1; transform: translateY(0);}
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
